    /**
     * Tests getting all Collaterals.
     *
     * @return    Collection
     */
    public List<Collateral> testGetAll() throws Throwable {
    LOGGER.info( "CollateralTest:testGetAll() - Retrieving Collection of Collaterals:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all Collateral : " );
    List<Collateral> collection  = null;

    try {
        // call the static get method on the CollateralService
        collection = service.getAllCollateral();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            Collateral currEntity  = null;
            Iterator<Collateral> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getCollateralId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

